/**
 * Treatment categories and conditions: the single source of truth for the
 * Treatments mega-menu, category pages, condition pages and the sitemap.
 *
 * Do not import this file from pages or components. Go through
 * `src/lib/treatments.ts`, so the data source can later be swapped for a
 * database without touching any page.
 *
 * Content rules: use neutral wording ("Homoeopathic care for …", "Conditions
 * we see"). Never use "cure", "guaranteed", "permanent relief" or "100% safe".
 *
 * The `content` paragraphs are PLACEHOLDERS generated by `placeholderContent()`.
 * Replace them with text written or reviewed by the doctor before launch.
 */

const SITE_NAME = 'Harivin Multispecialty Homeo Clinic';

export type CategoryIcon =
  'lungs' | 'ear' | 'skin' | 'bone' | 'digestive' | 'women' | 'chronic' | 'child' | 'mind' | 'plus';

export interface CategoryRecord {
  slug: string;
  name: string;
  icon: CategoryIcon;
  /** One line, used on cards and in the mega-menu. */
  shortDescription: string;
  /** Intro paragraph at the top of the category page. */
  intro: string;
  seoTitle: string;
  seoDescription: string;
}

export interface ConditionRecord {
  slug: string;
  name: string;
  /**
   * Categories this condition is listed under. The FIRST one is the primary
   * category, used for breadcrumbs and "related conditions". A condition has
   * one canonical page however many categories it appears in.
   */
  categorySlugs: string[];
  shortDescription: string;
  /** Body paragraphs, rendered in order. */
  content: string[];
  seoTitle: string;
  seoDescription: string;
}

