/** Generic placeholder body text. Replace per condition before launch. */
function placeholderContent(phrase: string, note?: string): string[] {
  const paragraphs = [
    `At ${SITE_NAME}, homoeopathic care for ${phrase} begins with a detailed consultation. Along with your main symptoms, the doctor asks about your general health, sleep, appetite, emotional wellbeing and personal and family medical history, so that the remedy is chosen for you as an individual and not for the condition alone.`,
    'Your progress is reviewed at regular follow-up visits, and the remedy or dosage may be adjusted as things change. Many people continue the treatment prescribed by their other doctors while receiving homoeopathic care. Please bring a list of your current medicines and any recent reports to your first visit.',
    'How each person responds to treatment varies. If your symptoms are severe, getting worse, or new and unexplained, please see a doctor promptly for diagnosis.',
  ];
  return note ? [...paragraphs, note] : paragraphs;
}

interface ConditionInput {
  slug: string;
  name: string;
  categorySlugs: string[];
  shortDescription: string;
  /** How the name reads mid-sentence, if not simply lower-cased. */
  phrase?: string;
  /** Extra safety note appended to the content. */
  note?: string;
}

function condition({
  slug,
  name,
  categorySlugs,
  shortDescription,
  phrase,
  note,
}: ConditionInput): ConditionRecord {
  return {
    slug,
    name,
    categorySlugs,
    shortDescription,
    content: placeholderContent(phrase ?? name.toLowerCase(), note),
    seoTitle: seoTitle(name),
    seoDescription: `${shortDescription} Book a consultation at ${SITE_NAME}.`,
  };
}

